    for start, end in intervals:
        if start > end:
            raise ValueError("Invalid interval: start > end")
        if start < end:
            valid.append((start, end))

    if not valid:
        return []

    valid.sort()
    merged = [valid[0]]

    for current in valid[1:]:
        last = merged[-1]
        if current[0] > last[1]:
            merged.append(current)
        else:
            merged[-1] = (last[0], max(last[1], current[1]))

    return merged

